-- entries: 26 records
insert into content.entries ("author","body","cover_url","created_at","created_by","data","environment_id","excerpt","id","locale","metadata","project_id","published_at","slug","status","title","type","updated_at")
select "author","body","cover_url","created_at","created_by","data","environment_id","excerpt","id","locale","metadata","project_id","published_at","slug","status","title","type","updated_at" from jsonb_populate_recordset(null::content.entries, $seed_e369cbcfe57f$[{"id":"aa6036da-5d05-5260-a1dc-d8d3617ddb5a","title":"Welcome to Geiger Content Studio","type":"Page","slug":"demo-welcome-to-geiger-content-studio","status":"Published","excerpt":"Create, review, personalize, and deliver content from one connected workspace.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Welcome to Geiger Content Studio\"},{\"type\":\"paragraph\",\"text\":\"Create, review, personalize, and deliver content from one connected workspace.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"Start with the editorial library. Each entry has an owner, a locale, an environment, and a clear publication state. The demo combines a product journal, a help center, and a campaign landing page so you can follow content from a draft to a measurable visitor experience.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Maya Patel","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/f58f81a1-0f89-57bd-a8a2-ac41ee017b5c/cover.png","published_at":"2026-08-30T10:00:00.000Z","created_at":"2026-08-19T10:00:00.000Z","updated_at":"2026-09-29T10:00:00.000Z","data":{"summary":"Create, review, personalize, and deliver content from one connected workspace.","reading_minutes":3,"featured":true,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Getting started"],"tags":["Getting started"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"Welcome to Geiger Content Studio","seoDescription":"Create, review, personalize, and deliver content from one connected workspace.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef","title":"Your first content project in fifteen minutes","type":"Guide","slug":"demo-your-first-content-project-in-fifteen-minutes","status":"Published","excerpt":"A practical path from an empty workspace to a published page.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Your first content project in fifteen minutes\"},{\"type\":\"paragraph\",\"text\":\"A practical path from an empty workspace to a published page.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"Choose a default locale and create an Article content type. Add a short excerpt, a reading time, and a featured flag. Write a clear title and two useful sections, invite a reviewer, and publish the approved version. Open the delivery URL and compare the saved snapshot with your next edit.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Alex Morgan","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/b18c7b59-440d-599a-a2b5-48ac711bfc7e/cover.png","published_at":"2026-08-30T10:00:00.000Z","created_at":"2026-08-19T10:00:00.000Z","updated_at":"2026-09-30T10:00:00.000Z","data":{"summary":"A practical path from an empty workspace to a published page.","reading_minutes":4,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Getting started"],"tags":["Getting started"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"Your first content project in fifteen minutes","seoDescription":"A practical path from an empty workspace to a published page.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"a22e5cbf-ac3d-5821-a42a-0960fbd0b586","title":"A launch page for teams that move together","type":"Page","slug":"demo-a-launch-page-for-teams-that-move-together","status":"Published","excerpt":"Bring your launch story, supporting guides, and next action into one page.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"A launch page for teams that move together\"},{\"type\":\"paragraph\",\"text\":\"Bring your launch story, supporting guides, and next action into one page.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"A successful launch page gives visitors a reason to care, shows how the product works, and offers one next step. Use a reusable hero block for the headline and a call to action block for the trial link. Connect the page to onboarding guides through entry references rather than copying the same text.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Priya Shah","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/3a6d5aa1-e77b-520d-aee8-b5672e425d40/cover.png","published_at":"2026-08-30T10:00:00.000Z","created_at":"2026-08-19T10:00:00.000Z","updated_at":"2026-10-01T10:00:00.000Z","data":{"summary":"Bring your launch story, supporting guides, and next action into one page.","reading_minutes":5,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Launch planning"],"tags":["Launch planning"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"A launch page for teams that move together","seoDescription":"Bring your launch story, supporting guides, and next action into one page.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"60a7ce58-ca30-554b-ac5e-f8ea9a2d5713","title":"Model once, publish everywhere","type":"Article","slug":"demo-model-once-publish-everywhere","status":"Published","excerpt":"Use structured fields to keep websites, campaigns, and apps consistent.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Model once, publish everywhere\"},{\"type\":\"paragraph\",\"text\":\"Use structured fields to keep websites, campaigns, and apps consistent.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"Structured content separates the information from the presentation. Editors enter validated values and designers decide how those values appear on each channel. Begin with the fields your team actually needs: summary, reading time, featured status, and a related guide. Localize the summary and reuse the related guide by reference.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Noah Kim","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/e7abd619-8bff-5512-aed7-7a7d963516fe/cover.png","published_at":"2026-08-31T10:00:00.000Z","created_at":"2026-08-20T10:00:00.000Z","updated_at":"2026-10-02T10:00:00.000Z","data":{"summary":"Use structured fields to keep websites, campaigns, and apps consistent.","reading_minutes":6,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Content modeling"],"tags":["Content modeling"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"Model once, publish everywhere","seoDescription":"Use structured fields to keep websites, campaigns, and apps consistent.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"a8bd90ab-e06b-5a1a-a0ea-779f068afc94","title":"The editorial review checklist","type":"Guide","slug":"demo-the-editorial-review-checklist","status":"Published","excerpt":"Make approval predictable with a short, repeatable review routine.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"The editorial review checklist\"},{\"type\":\"paragraph\",\"text\":\"Make approval predictable with a short, repeatable review routine.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"Check the title for clarity, the excerpt for usefulness, the cover for descriptive alternative text, and every reference for relevance. Ask the assigned reviewer to resolve factual questions in comments. Record the approved version before publication so the team can see exactly what changed later.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Maya Patel","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/f83410fa-104f-5dfd-a254-a467b03959c3/cover.png","published_at":"2026-08-31T10:00:00.000Z","created_at":"2026-08-20T10:00:00.000Z","updated_at":"2026-09-29T10:00:00.000Z","data":{"summary":"Make approval predictable with a short, repeatable review routine.","reading_minutes":7,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Editorial operations"],"tags":["Editorial operations"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"The editorial review checklist","seoDescription":"Make approval predictable with a short, repeatable review routine.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"70d212f7-ed39-5dbf-ae06-7e61586f8f9a","title":"Publish with confidence across environments","type":"Doc","slug":"demo-publish-with-confidence-across-environments","status":"Published","excerpt":"Use production, staging, and sandbox to separate live content from experiments.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Publish with confidence across environments\"},{\"type\":\"paragraph\",\"text\":\"Use production, staging, and sandbox to separate live content from experiments.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"Production holds the public experience. Staging is for stakeholder preview and sandbox is for trying new models. Choose the environment before creating a delivery site. Verify that the fallback entry is published and that a targeted variant belongs to the same project. Keep drafts out of public delivery.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Alex Morgan","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/78cf2853-c1ac-5d8a-a421-7c0fe8f3bcd8/cover.png","published_at":"2026-08-31T10:00:00.000Z","created_at":"2026-08-20T10:00:00.000Z","updated_at":"2026-09-30T10:00:00.000Z","data":{"summary":"Use production, staging, and sandbox to separate live content from experiments.","reading_minutes":3,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Delivery"],"tags":["Delivery"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"Publish with confidence across environments","seoDescription":"Use production, staging, and sandbox to separate live content from experiments.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"b9ec220e-2ecf-546a-a4b6-3b9309d9a867","title":"Personalization that starts with consent","type":"Article","slug":"demo-personalization-that-starts-with-consent","status":"Published","excerpt":"Respect visitor choices while still delivering useful default content.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Personalization that starts with consent\"},{\"type\":\"paragraph\",\"text\":\"Respect visitor choices while still delivering useful default content.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"A visitor can accept analytics while declining personalization. Store each purpose independently and use a published fallback when personalization is denied. Profiles in this demonstration include granted, pending, and denied choices. You can test each scenario without using a real customer's identity.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Priya Shah","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/29033177-7e56-53e7-aad3-6133175ba334/cover.png","published_at":"2026-09-01T10:00:00.000Z","created_at":"2026-08-21T10:00:00.000Z","updated_at":"2026-10-01T10:00:00.000Z","data":{"summary":"Respect visitor choices while still delivering useful default content.","reading_minutes":4,"featured":true,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Personalization"],"tags":["Personalization"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"Personalization that starts with consent","seoDescription":"Respect visitor choices while still delivering useful default content.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"fc6523d0-f490-50c9-ad8d-1318ea24a34e","title":"Build a useful returning-reader experience","type":"Guide","slug":"demo-build-a-useful-returning-reader-experience","status":"Published","excerpt":"Turn repeat visits into a clearer path through your library.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Build a useful returning-reader experience\"},{\"type\":\"paragraph\",\"text\":\"Turn repeat visits into a clearer path through your library.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"Start with a segment for readers who viewed at least three articles. Offer an advanced guide when their topic stage is engaged and a beginner guide when they are curious. Cap repeated impressions so a promotional card does not dominate the experience. Keep a default option for people who do not match a rule.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Noah Kim","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/f921931a-ede9-5a8b-ae09-ded1db16c342/cover.png","published_at":"2026-09-01T10:00:00.000Z","created_at":"2026-08-21T10:00:00.000Z","updated_at":"2026-10-02T10:00:00.000Z","data":{"summary":"Turn repeat visits into a clearer path through your library.","reading_minutes":5,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Personalization"],"tags":["Personalization"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"Build a useful returning-reader experience","seoDescription":"Turn repeat visits into a clearer path through your library.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"2c0c9921-c217-5e5b-a205-2701e6af1174","title":"Test a headline without losing the story","type":"Article","slug":"demo-test-a-headline-without-losing-the-story","status":"Published","excerpt":"Compare two promises while keeping the audience and goal consistent.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Test a headline without losing the story\"},{\"type\":\"paragraph\",\"text\":\"Compare two promises while keeping the audience and goal consistent.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"A headline test should change one meaningful idea. The control emphasizes faster publishing and the challenger emphasizes team confidence. Split eligible traffic evenly, reserve a small holdout, and measure trial starts. Review exposures and conversions together before calling a winner.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Maya Patel","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/1dc4e67f-2241-55b4-a822-212dc5d33c67/cover.png","published_at":"2026-09-01T10:00:00.000Z","created_at":"2026-08-21T10:00:00.000Z","updated_at":"2026-09-29T10:00:00.000Z","data":{"summary":"Compare two promises while keeping the audience and goal consistent.","reading_minutes":6,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Experimentation"],"tags":["Experimentation"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"Test a headline without losing the story","seoDescription":"Compare two promises while keeping the audience and goal consistent.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"af4694ad-e480-54a8-a098-c8b7aa670b91","title":"Read the metrics behind a launch","type":"Guide","slug":"demo-read-the-metrics-behind-a-launch","status":"Published","excerpt":"Understand reach, engagement, and conversion across thirty days.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Read the metrics behind a launch\"},{\"type\":\"paragraph\",\"text\":\"Understand reach, engagement, and conversion across thirty days.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"Views tell you how many times content was seen; conversions show whether the next step happened. Compare a rising week with the previous week and inspect the entry behind each spike. The synthetic events in this demo are rolled up into matching daily metrics, so the charts and event stream tell the same story.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Alex Morgan","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/b82f9ec0-0a43-54a9-af6b-e25a2b5d649a/cover.png","published_at":"2026-09-02T10:00:00.000Z","created_at":"2026-08-22T10:00:00.000Z","updated_at":"2026-09-30T10:00:00.000Z","data":{"summary":"Understand reach, engagement, and conversion across thirty days.","reading_minutes":7,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Analytics"],"tags":["Analytics"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"Read the metrics behind a launch","seoDescription":"Understand reach, engagement, and conversion across thirty days.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"42979e3f-d507-5780-ae9c-f67e534a4ba5","title":"Localize a help center with fallback languages","type":"Guide","slug":"demo-localize-a-help-center-with-fallback-languages","status":"Published","excerpt":"Give translators a stable source and readers a useful fallback.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Localize a help center with fallback languages\"},{\"type\":\"paragraph\",\"text\":\"Give translators a stable source and readers a useful fallback.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"Publish the English source before creating Hindi and French editions. Localize the summary and body while retaining references to the same conceptual guide. Set English as the fallback language and review translated snapshots before release. A missing translation should never become an empty help page.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Priya Shah","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/e6a1c03d-966c-531d-a3b5-ded0cacd9049/cover.png","published_at":"2026-09-02T10:00:00.000Z","created_at":"2026-08-22T10:00:00.000Z","updated_at":"2026-10-01T10:00:00.000Z","data":{"summary":"Give translators a stable source and readers a useful fallback.","reading_minutes":3,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Localization"],"tags":["Localization"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"Localize a help center with fallback languages","seoDescription":"Give translators a stable source and readers a useful fallback.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"7b04ca1d-d901-5b53-acfe-7094cd4ff7a0","title":"Reusable blocks for a consistent brand","type":"Doc","slug":"demo-reusable-blocks-for-a-consistent-brand","status":"Published","excerpt":"Compose pages from hero, quote, feature, and call to action blocks.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Reusable blocks for a consistent brand\"},{\"type\":\"paragraph\",\"text\":\"Compose pages from hero, quote, feature, and call to action blocks.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"Blocks keep repeated content patterns consistent. A hero carries a headline and supporting line, a feature block explains a benefit, and a quote adds evidence. Instances store entry-specific values and an explicit position. Editors can reorder those instances while the schema remains reusable.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Noah Kim","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/7345b8dd-d2bc-5e69-a563-1824cab418ae/cover.png","published_at":"2026-09-02T10:00:00.000Z","created_at":"2026-08-22T10:00:00.000Z","updated_at":"2026-10-02T10:00:00.000Z","data":{"summary":"Compose pages from hero, quote, feature, and call to action blocks.","reading_minutes":4,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Content modeling"],"tags":["Content modeling"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"Reusable blocks for a consistent brand","seoDescription":"Compose pages from hero, quote, feature, and call to action blocks.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"5397efc6-b2eb-580b-a382-3b9a4f1f3c93","title":"Launching the autumn product journal","type":"Article","slug":"demo-launching-the-autumn-product-journal","status":"Published","excerpt":"A connected release story for a distributed editorial team.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Launching the autumn product journal\"},{\"type\":\"paragraph\",\"text\":\"A connected release story for a distributed editorial team.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"The autumn journal brings together product updates, practical tutorials, and customer stories. The first release focuses on structured content and the second introduces audience journeys. Review the launch collection in order, check cover assets, and use the homepage hero slot to direct readers to the most relevant introduction.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Maya Patel","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/f58f81a1-0f89-57bd-a8a2-ac41ee017b5c/cover.png","published_at":"2026-09-03T10:00:00.000Z","created_at":"2026-08-23T10:00:00.000Z","updated_at":"2026-09-29T10:00:00.000Z","data":{"summary":"A connected release story for a distributed editorial team.","reading_minutes":5,"featured":true,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Launch planning"],"tags":["Launch planning"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"Launching the autumn product journal","seoDescription":"A connected release story for a distributed editorial team.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"66ead180-0695-5c42-a793-cbe0f9b8ea35","title":"API delivery quickstart","type":"Doc","slug":"demo-api-delivery-quickstart","status":"Published","excerpt":"Read published content through REST and GraphQL.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"API delivery quickstart\"},{\"type\":\"paragraph\",\"text\":\"Read published content through REST and GraphQL.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"Request the entries endpoint with an explicit project ID and inspect the returned title, excerpt, and body. GraphQL lets a client choose the fields it needs. Delivery excludes drafts and private entries. Use the collect endpoint to record a page view only after analytics consent is granted.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Alex Morgan","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/b18c7b59-440d-599a-a2b5-48ac711bfc7e/cover.png","published_at":"2026-09-03T10:00:00.000Z","created_at":"2026-08-23T10:00:00.000Z","updated_at":"2026-09-30T10:00:00.000Z","data":{"summary":"Read published content through REST and GraphQL.","reading_minutes":6,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Delivery"],"tags":["Delivery"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"API delivery quickstart","seoDescription":"Read published content through REST and GraphQL.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"59042e49-85dc-5db1-aa0f-8d9e6f75f0ae","title":"Taxonomy that readers can navigate","type":"Article","slug":"demo-taxonomy-that-readers-can-navigate","status":"Published","excerpt":"Build a small topic hierarchy instead of an unbounded tag list.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Taxonomy that readers can navigate\"},{\"type\":\"paragraph\",\"text\":\"Build a small topic hierarchy instead of an unbounded tag list.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"Group editorial operations and launch planning under Team practice. Group delivery and modeling under Platform. Use terms to connect related guides and expose a readable browsing path. Prefer a few well-defined topics over synonyms that split the same audience across multiple labels.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Priya Shah","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/3a6d5aa1-e77b-520d-aee8-b5672e425d40/cover.png","published_at":"2026-09-03T10:00:00.000Z","created_at":"2026-08-23T10:00:00.000Z","updated_at":"2026-10-01T10:00:00.000Z","data":{"summary":"Build a small topic hierarchy instead of an unbounded tag list.","reading_minutes":7,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Content modeling"],"tags":["Content modeling"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"Taxonomy that readers can navigate","seoDescription":"Build a small topic hierarchy instead of an unbounded tag list.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"8538828a-cf4c-5488-a9ad-4c0d77c885d9","title":"Version history as an editorial safety net","type":"Guide","slug":"demo-version-history-as-an-editorial-safety-net","status":"Published","excerpt":"Compare, explain, and recover important content changes.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Version history as an editorial safety net\"},{\"type\":\"paragraph\",\"text\":\"Compare, explain, and recover important content changes.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"Every publish snapshot preserves the complete entry payload. Compare the first introduction with the revised introduction to see changes in title, excerpt, and typed data. A rollback restores a reviewed snapshot and creates a traceable new decision. Keep unresolved comments attached to the entry rather than hiding the discussion.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Noah Kim","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/e7abd619-8bff-5512-aed7-7a7d963516fe/cover.png","published_at":"2026-09-04T10:00:00.000Z","created_at":"2026-08-24T10:00:00.000Z","updated_at":"2026-10-02T10:00:00.000Z","data":{"summary":"Compare, explain, and recover important content changes.","reading_minutes":3,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Editorial operations"],"tags":["Editorial operations"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"Version history as an editorial safety net","seoDescription":"Compare, explain, and recover important content changes.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"3242a6f2-6ad6-5a91-a32b-7d7674419e5d","title":"A homepage for first-time readers","type":"Page","slug":"demo-a-homepage-for-first-time-readers","status":"Published","excerpt":"Offer a short explanation and a clear first guide.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"A homepage for first-time readers\"},{\"type\":\"paragraph\",\"text\":\"Offer a short explanation and a clear first guide.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"Welcome new readers with a plain-language promise: create useful content and deliver it confidently. The introductory homepage variant links to the first-project guide. Returning readers can receive an advanced workflow variant, while a consent-denied reader receives this safe default.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Maya Patel","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/f83410fa-104f-5dfd-a254-a467b03959c3/cover.png","published_at":"2026-09-04T10:00:00.000Z","created_at":"2026-08-24T10:00:00.000Z","updated_at":"2026-09-29T10:00:00.000Z","data":{"summary":"Offer a short explanation and a clear first guide.","reading_minutes":4,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Getting started"],"tags":["Getting started"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"A homepage for first-time readers","seoDescription":"Offer a short explanation and a clear first guide.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"89876ac2-7ca0-5d2d-ac93-114c3d99eb4b","title":"A homepage for growing editorial teams","type":"Page","slug":"demo-a-homepage-for-growing-editorial-teams","status":"Published","excerpt":"Lead with collaboration, approvals, and reusable publishing routines.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"A homepage for growing editorial teams\"},{\"type\":\"paragraph\",\"text\":\"Lead with collaboration, approvals, and reusable publishing routines.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"Growing teams need a shared way to decide what is ready. Assign a reviewer, give each article a due date, and track progress through Draft, In review, and Published. This page highlights those routines and directs experienced readers to the review checklist.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Alex Morgan","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/78cf2853-c1ac-5d8a-a421-7c0fe8f3bcd8/cover.png","published_at":"2026-09-04T10:00:00.000Z","created_at":"2026-08-24T10:00:00.000Z","updated_at":"2026-09-30T10:00:00.000Z","data":{"summary":"Lead with collaboration, approvals, and reusable publishing routines.","reading_minutes":5,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Editorial operations"],"tags":["Editorial operations"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"A homepage for growing editorial teams","seoDescription":"Lead with collaboration, approvals, and reusable publishing routines.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"819fba91-fceb-5a64-a1a3-d218543cccae","title":"Faster publishing, fewer handoffs","type":"Page","slug":"demo-faster-publishing-fewer-handoffs","status":"Published","excerpt":"The control page for the launch headline experiment.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Faster publishing, fewer handoffs\"},{\"type\":\"paragraph\",\"text\":\"The control page for the launch headline experiment.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"Create a reusable content model, write once, and deliver the same story across channels. The control headline leads with speed. Its call to action invites the visitor to start a content project. Compare its conversion rate with the confidence-focused challenger in the experiment report.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Priya Shah","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/29033177-7e56-53e7-aad3-6133175ba334/cover.png","published_at":"2026-09-05T10:00:00.000Z","created_at":"2026-08-25T10:00:00.000Z","updated_at":"2026-10-01T10:00:00.000Z","data":{"summary":"The control page for the launch headline experiment.","reading_minutes":6,"featured":true,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Experimentation"],"tags":["Experimentation"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"Faster publishing, fewer handoffs","seoDescription":"The control page for the launch headline experiment.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"5a6d4ea9-3925-5fb1-a048-1aec5dbca6b5","title":"Give your team confidence to publish","type":"Page","slug":"demo-give-your-team-confidence-to-publish","status":"Published","excerpt":"The challenger page for the launch headline experiment.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Give your team confidence to publish\"},{\"type\":\"paragraph\",\"text\":\"The challenger page for the launch headline experiment.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"Make every publication a team decision you can explain. Structured fields, review comments, and version history show what changed and who approved it. The challenger headline leads with confidence and keeps the same trial action as the control.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Noah Kim","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/f921931a-ede9-5a8b-ae09-ded1db16c342/cover.png","published_at":"2026-09-05T10:00:00.000Z","created_at":"2026-08-25T10:00:00.000Z","updated_at":"2026-10-02T10:00:00.000Z","data":{"summary":"The challenger page for the launch headline experiment.","reading_minutes":7,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Experimentation"],"tags":["Experimentation"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"Give your team confidence to publish","seoDescription":"The challenger page for the launch headline experiment.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"342cea5a-2c1f-56e0-aaf9-78582298b6cf","title":"Managing media without duplicate uploads","type":"Guide","slug":"demo-managing-media-without-duplicate-uploads","status":"Published","excerpt":"Keep a usable asset library with folders, alternative text, and checksums.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Managing media without duplicate uploads\"},{\"type\":\"paragraph\",\"text\":\"Keep a usable asset library with folders, alternative text, and checksums.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"Name a cover for its purpose and place it in a campaign folder. Use a checksum to spot byte-identical uploads and review visually similar covers before deleting anything. The demo includes one intentional duplicate cover so the duplicate inspection screen has a concrete example.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Maya Patel","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/1dc4e67f-2241-55b4-a822-212dc5d33c67/cover.png","published_at":"2026-09-05T10:00:00.000Z","created_at":"2026-08-25T10:00:00.000Z","updated_at":"2026-09-29T10:00:00.000Z","data":{"summary":"Keep a usable asset library with folders, alternative text, and checksums.","reading_minutes":3,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Media operations"],"tags":["Media operations"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"Managing media without duplicate uploads","seoDescription":"Keep a usable asset library with folders, alternative text, and checksums.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"38620e46-ab7b-56d4-a230-e2a071dd170d","title":"Designing fair frequency caps","type":"Article","slug":"demo-designing-fair-frequency-caps","status":"Published","excerpt":"Limit repetition while keeping recommendations relevant.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Designing fair frequency caps\"},{\"type\":\"paragraph\",\"text\":\"Limit repetition while keeping recommendations relevant.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"A frequency cap limits the impressions a visitor receives within a defined window. Apply a short cap to campaign calls to action and a longer window to onboarding prompts. Check the visitor history before delivery and retain a fallback when the eligible set becomes empty.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Alex Morgan","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/b82f9ec0-0a43-54a9-af6b-e25a2b5d649a/cover.png","published_at":"2026-09-06T10:00:00.000Z","created_at":"2026-08-26T10:00:00.000Z","updated_at":"2026-09-30T10:00:00.000Z","data":{"summary":"Limit repetition while keeping recommendations relevant.","reading_minutes":4,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Personalization"],"tags":["Personalization"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"Designing fair frequency caps","seoDescription":"Limit repetition while keeping recommendations relevant.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"6bb181d7-e5c4-5979-a6dd-1eb4fb4437e6","title":"Governance for a small content team","type":"Doc","slug":"demo-governance-for-a-small-content-team","status":"Published","excerpt":"Make permissions, retention, and editorial standards visible.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Governance for a small content team\"},{\"type\":\"paragraph\",\"text\":\"Make permissions, retention, and editorial standards visible.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"Writers can edit drafts, publishers can approve delivery, and analysts can inspect aggregated results. Editorial policies describe the team's standards; retention rules describe what happens to old data. Demo credentials are revoked and integrations are paused so their records can be inspected without connecting outside services.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Priya Shah","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/e6a1c03d-966c-531d-a3b5-ded0cacd9049/cover.png","published_at":"2026-09-06T10:00:00.000Z","created_at":"2026-08-26T10:00:00.000Z","updated_at":"2026-10-01T10:00:00.000Z","data":{"summary":"Make permissions, retention, and editorial standards visible.","reading_minutes":5,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Editorial operations"],"tags":["Editorial operations"],"visibility":"public","campaign":"Autumn product journal","seoTitle":"Governance for a small content team","seoDescription":"Make permissions, retention, and editorial standards visible.","demoSeed":"geiger-content-demonstrator-v1","synthetic":true},"project_id":"ebcc7910-1a0e-4e91-8c3b-752f3c4292d3","created_by":"39149c4b-526f-445b-8a8c-ea3898e9c50c"},{"id":"85b37e18-6401-5da4-adcc-85a6cedc7e08","title":"Connecting a product catalog to editorial content","type":"Doc","slug":"demo-connecting-a-product-catalog-to-editorial-content","status":"Published","excerpt":"Represent external sources without duplicating the source of truth.","body":"{\"blocks\":[{\"type\":\"heading\",\"text\":\"Connecting a product catalog to editorial content\"},{\"type\":\"paragraph\",\"text\":\"Represent external sources without duplicating the source of truth.\"},{\"type\":\"heading\",\"text\":\"Put it into practice\"},{\"type\":\"paragraph\",\"text\":\"An external source records its type, endpoint, status, and mapping. Reference catalog items from an entry and keep the source credentials on the server. This demonstration includes disconnected API, RSS, CSV, and CMS configurations with example endpoints and seeded mapping metadata.\"},{\"type\":\"paragraph\",\"text\":\"Try this in the demonstration workspace: inspect the linked records, compare a saved version, and follow the related guide. All audience and performance examples are synthetic.\"}]}","author":"Noah Kim","locale":"en","environment_id":"2fd256c9-422c-56d7-a23b-b5280b6b222f","cover_url":"https://dyjiyzcsdaeuxtueslqr.supabase.co/storage/v1/object/public/content/assets/ebcc7910-1a0e-4e91-8c3b-752f3c4292d3/7345b8dd-d2bc-5e69-a563-1824cab418ae/cover.png","published_at":"2026-09-06T10:00:00.000Z","created_at":"2026-08-26T10:00:00.000Z","updated_at":"2026-10-02T10:00:00.000Z","data":{"summary":"Represent external sources without duplicating the source of truth.","reading_minutes":6,"featured":false,"review_date":"2026-10-17","related_guide":"bc35f4b0-488c-5044-a6e8-e8d58e62fcef"},"metadata":{"topics":["Content 